archivos.codigo:
:root {
  color-scheme: dark;
  padding-top: env(safe-area-inset-top, 0px);
  padding-bottom: env(safe-area-inset-bottom, 0px);
  --bg: #080a14;
  --panel: #0f1325;
  --line: #262d4d;
  --fg: #e6e9f6;
  --muted: #8f98bb;
  --rose: #ff86b6;
  --cyan: #60dcff;
  --amber: #ffbe78;
  --mint: #78ffd2;
  --display: "Space Grotesk", ui-sans-serif, system-ui, sans-serif;
  --body: "Inter", ui-sans-serif, system-ui, sans-serif;
  --mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-padding-top: env(safe-area-inset-top, 0px);
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font: 15px/1.55 var(--body);
  padding-block: 28px 48px;
  padding-left: max(16px, env(safe-area-inset-left, 0px));
  padding-right: max(16px, env(safe-area-inset-right, 0px));
}

.view-dock {
  display: flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin: 0 0 20px auto;
}

.view-tabs {
  display: flex;
  gap: 4px;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--panel);
}

.view-tab,
.play-floating,
.next-floating {
  border: 0;
  border-radius: 999px;
  padding: 8px 14px;
  background: transparent;
  color: var(--muted);
  font: 600 12px var(--mono);
  cursor: pointer;
}

.view-tab[aria-pressed="true"] {
  background: var(--rose);
  color: #080a14;
}

.play-floating {
  margin-top: 0;
  border: 1px solid var(--rose);
  color: var(--fg);
}

.play-floating[aria-pressed="true"] {
  background: var(--rose);
  color: #080a14;
}

body[data-view="normal"] .play-floating,
body[data-view="normal"] .next-floating {
  display: none;
}

img {
  max-width: 100%;
}

[hidden]:not([hidden="until-found" i]) {
  display: none !important;
}

main {
  max-width: 1000px;
  margin-inline: auto;
}

h1 {
  font: 600 clamp(1.8rem, 5vw, 2.6rem)/1.1 var(--display);
  letter-spacing: -0.01em;
  margin: 0 0 12px;
  text-wrap: balance;
}

.lead {
  color: var(--muted);
  max-width: 62ch;
  margin: 0;
}

.stage {
  position: relative;
  height: clamp(250px, 46vw, 400px);
  margin-block: 24px 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  background: #05060d;
}

canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.hud {
  position: absolute;
  inset: 0 0 auto 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 8px 16px;
  padding: 14px 16px;
  font: 12px/1.4 var(--mono);
  color: var(--muted);
  text-shadow: 0 1px 8px #05060d;
}

.hud strong {
  display: block;
  color: var(--fg);
  font: 600 18px/1.3 var(--display);
}

.hud .right {
  text-align: right;
  margin-left: auto;
}

.bar {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  font: 12px var(--mono);
  color: var(--muted);
}

.bar input {
  flex: 0 1 220px;
  min-width: 0;
  accent-color: var(--rose);
}

.tracks {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 270px), 1fr));
  gap: 16px;
}

.card {
  --c: var(--rose);
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
  padding: 18px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  transition: border-color 0.2s;
}

.card.selected {
  border-color: color-mix(in srgb, var(--c) 55%, var(--line));
}

.card.on {
  border-color: var(--c);
}

.card h2 {
  font: 600 1.3rem/1.2 var(--display);
  margin: 0;
}

.mood {
  color: var(--muted);
  margin: 0;
  font-size: 14px;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  font: 12px var(--mono);
}

.chips span {
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 2px 10px;
  color: var(--muted);
}

.map {
  display: flex;
  gap: 3px;
  height: 8px;
}

.seg {
  background: var(--line);
  border-radius: 2px;
  transition: background 0.3s;
}

.seg.done {
  background: color-mix(in srgb, var(--c) 40%, var(--line));
}

.seg.now {
  background: var(--c);
}

.where {
  font: 12px/1.4 var(--mono);
  color: var(--muted);
  min-height: 1.4em;
}

button.play {
  margin-top: auto;
  background: transparent;
  color: var(--fg);
  border: 1px solid var(--c);
  border-radius: 8px;
  padding: 10px 14px;
  font: 600 14px var(--body);
  cursor: pointer;
}

button.play:hover {
  background: color-mix(in srgb, var(--c) 18%, transparent);
}

button.play[aria-pressed="true"] {
  background: var(--c);
  color: #080a14;
}

button.play.next-floating {
  margin-top: 0;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 14px;
  color: var(--muted);
  font: 600 12px var(--mono);
}

button.play.next-floating:hover {
  background: var(--panel);
  color: var(--fg);
}

:focus-visible {
  outline: 2px solid var(--fg);
  outline-offset: 2px;
}

.note {
  color: var(--muted);
  font-size: 13px;
  max-width: 70ch;
  margin: 22px 0 0;
}

body[data-view="immersive"] {
  padding: 0;
  overflow: hidden;
}

body[data-view="immersive"] main {
  max-width: none;
  margin: 0;
}

body[data-view="immersive"] main > :not(.stage) {
  display: none;
}

body[data-view="immersive"] .stage {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  margin: 0;
  border: 0;
  border-radius: 0;
}

body[data-view="immersive"] .hud {
  padding: max(24px, env(safe-area-inset-top, 0px)) max(24px, env(safe-area-inset-right, 0px))
    max(24px, env(safe-area-inset-bottom, 0px)) max(24px, env(safe-area-inset-left, 0px));
  font-size: 14px;
}

body[data-view="immersive"] .hud strong {
  font-size: clamp(24px, 4vw, 44px);
}

body[data-view="immersive"] .view-dock {
  position: fixed;
  z-index: 2;
  inset: auto auto max(20px, env(safe-area-inset-bottom, 0px)) 50%;
  transform: translateX(-50%);
  margin: 0;
  padding: 6px;
  background: color-mix(in srgb, var(--panel) 80%, transparent);
  border: 1px solid var(--line);
  border-radius: 999px;
  backdrop-filter: blur(10px);
}

body[data-view="immersive"] .view-tabs {
  padding: 0;
  border: 0;
  background: transparent;
}

import { songs } from "./modules/song.js";
import { Synth } from "./modules/synth.js";
import { Player } from "./modules/player.js";
import { Scene } from "./modules/scene.js";
import { createUI } from "./modules/ui.js";

let volume = 0.8;
let selected = songs[0];
let current = null;
let activation = null;

const scene = new Scene(document.querySelector("#scene"), selected);

const ui = createUI({
  songs,
  selected,
  onToggle: () => (activation ? activateAudio() : current ? stop() : play()),
  onSelect: (song) => (current?.song === song ? stop() : play(song)),
  onNext: () => {
    const next = songs[(songs.indexOf(selected) + 1) % songs.length];
    if (current) play(next);
    else selectSong(next);
  },
  onVolume: (value) => {
    volume = value;
    if (current)
      current.synth.out.gain.setTargetAtTime(volume, current.synth.ctx.currentTime, 0.02);
  },
});

ui.showSelected(selected);

const viewTabs = [...document.querySelectorAll(".view-tab")];

function setView(view) {
  document.body.dataset.view = view;
  viewTabs.forEach((tab) => {
    tab.setAttribute("aria-pressed", String(tab.dataset.viewTarget === view));
  });
  scene.resize();
}

viewTabs.forEach((tab) => {
  tab.addEventListener("click", () => setView(tab.dataset.viewTarget));
});
setView(document.body.dataset.view || "immersive");

function selectSong(song) {
  selected = song;
  scene.setSong(song);
  ui.showSelected(song);
}

function clearActivation() {
  if (!activation) return;
  activation.detach();
  activation = null;
  ui.setAudioPending(false);
}

function activateAudio() {
  if (!activation) return;
  const { synth, detach } = activation;
  activation = null;
  detach();
  synth.ctx.resume().then(
    () => {
      if (current?.synth === synth) ui.setAudioPending(false);
    },
    () => {
      if (current?.synth === synth) ui.showError("Tu navegador no permite audio aquí");
    },
  );
}

function stop() {
  clearActivation();
  if (!current) return;
  const { synth, player } = current;
  current = null;
  player.stop();
  synth.out.gain.setTargetAtTime(0, synth.ctx.currentTime, 0.06);
  setTimeout(() => synth.ctx.close(), 500);
  scene.setSource(null);
  ui.showStopped();
}

function play(song = selected) {
  stop();
  selectSong(song);
  let synth;
  try {
    synth = new Synth(volume);
  } catch {
    ui.showError("Tu navegador no permite audio aquí");
    return;
  }
  synth.ctx.resume().catch(() => {});

  const player = new Player(song, synth, (info) => {
    if (current?.song === song) ui.showPlaying(info);
  });

  current = { song, synth, player };
  scene.setSource(current);
  ui.showPlaying({ index: 0, bar: 0, total: song.totalBars, name: song.sections[0].name });
}

function autoStart() {
  play();
  if (!current) return;
  const synth = current.synth;
  if (synth.ctx.state === "running") return;
  ui.setAudioPending(true);
  const events = ["pointerdown", "keydown", "touchstart"];
  const onGesture = (event) => {
    if (event.target?.closest?.(".play")) return;
    activateAudio();
  };
  events.forEach((event) => addEventListener(event, onGesture, { capture: true }));
  activation = {
    synth,
    detach: () =>
      events.forEach((event) => removeEventListener(event, onGesture, { capture: true })),
  };
}

addEventListener("pagehide", stop);
scene.start();
autoStart();

const midi = (note) => 440 * 2 ** ((note - 69) / 12);

export class Synth {
  constructor(volume) {
    const ctx = (this.ctx = new AudioContext());

    this.out = ctx.createGain();
    this.out.gain.value = volume;

    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -16;
    comp.ratio.value = 4;
    comp.attack.value = 0.004;
    comp.release.value = 0.2;

    this.analyser = ctx.createAnalyser();
    this.analyser.fftSize = 1024;
    this.analyser.smoothingTimeConstant = 0.75;

    this.out.connect(comp).connect(this.analyser).connect(ctx.destination);

    this.drums = ctx.createGain();
    this.drums.connect(this.out);

    this.duck = ctx.createGain();
    this.duck.connect(this.out);

    this.dry = ctx.createGain();
    this.dry.connect(this.duck);

    this.verbSend = ctx.createGain();
    const verb = ctx.createConvolver();
    verb.buffer = this.impulse(2.8);
    this.verbSend.connect(verb).connect(this.duck);

    this.delay = ctx.createDelay(2);
    this.feedback = ctx.createGain();
    const tone = ctx.createBiquadFilter();
    tone.type = "lowpass";
    tone.frequency.value = 2600;
    this.delaySend = ctx.createGain();

    this.delaySend.connect(this.delay);
    this.delay.connect(tone);
    tone.connect(this.feedback).connect(this.delay);
    tone.connect(this.duck);

    this.noise = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
    const data = this.noise.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  }

  impulse(seconds) {
    const { ctx } = this;
    const length = Math.floor(ctx.sampleRate * seconds);
    const buffer = ctx.createBuffer(2, length, ctx.sampleRate);
    for (let channel = 0; channel < 2; channel++) {
      const data = buffer.getChannelData(channel);
      for (let i = 0; i < length; i++) {
        data[i] = (Math.random() * 2 - 1) * (1 - i / length) ** 3;
      }
    }
    return buffer;
  }

  setSong(song) {
    this.delay.delayTime.value = (60 / song.bpm) * 0.75;
    this.feedback.gain.value = song.fx.feedback;
    this.delaySend.gain.value = song.fx.delay;
    this.verbSend.gain.value = song.fx.verb;
  }

  env(param, time, peak, attack, decay) {
    param.setValueAtTime(0.0001, time);
    param.linearRampToValueAtTime(peak, time + attack);
    param.exponentialRampToValueAtTime(0.0001, time + attack + decay);
  }

  pump(time, depth) {
    this.duck.gain.setValueAtTime(depth, time);
    this.duck.gain.linearRampToValueAtTime(1, time + 0.22);
  }

  kick(time, vol, decay) {
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.frequency.setValueAtTime(160, time);
    osc.frequency.exponentialRampToValueAtTime(42, time + 0.14);
    this.env(gain.gain, time, vol, 0.002, decay);
    osc.connect(gain).connect(this.drums);
    osc.start(time);
    osc.stop(time + decay + 0.05);
  }

  hat(time, vol, open) {
    const source = this.ctx.createBufferSource();
    const highpass = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();
    source.buffer = this.noise;
    highpass.type = "highpass";
    highpass.frequency.value = 7500;
    this.env(gain.gain, time, vol, 0.001, open ? 0.22 : 0.045);
    source.connect(highpass).connect(gain).connect(this.drums);
    source.start(time, Math.random());
    source.stop(time + 0.3);
  }

  bass(time, note, duration, params) {
    const osc = this.ctx.createOscillator();
    const filter = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();
    osc.type = params.type;
    osc.frequency.value = midi(note);
    filter.type = "lowpass";
    filter.Q.value = params.q;
    filter.frequency.setValueAtTime(params.peak, time);
    filter.frequency.exponentialRampToValueAtTime(params.cutoff, time + params.decay);
    gain.gain.setValueAtTime(0.0001, time);
    gain.gain.linearRampToValueAtTime(params.vol, time + 0.006);
    gain.gain.setValueAtTime(params.vol, time + Math.max(0.01, duration - 0.04));
    gain.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    osc.connect(filter).connect(gain).connect(this.dry);
    osc.start(time);
    osc.stop(time + duration + 0.05);
  }

  pad(time, notes, duration, params) {
    const release = 1.2;
    const filter = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();
    filter.type = "lowpass";
    filter.frequency.value = params.cutoff;
    filter.Q.value = 0.7;
    gain.gain.setValueAtTime(0.0001, time);
    gain.gain.linearRampToValueAtTime(params.vol, time + params.attack);
    gain.gain.setValueAtTime(params.vol, time + duration);
    gain.gain.linearRampToValueAtTime(0.0001, time + duration + release);
    for (const note of notes) {
      for (const detune of [-8, 8]) {
        const osc = this.ctx.createOscillator();
        osc.type = "sawtooth";
        osc.frequency.value = midi(note);
        osc.detune.value = detune;
        osc.connect(filter);
        osc.start(time);
        osc.stop(time + duration + release + 0.1);
      }
    }
    filter.connect(gain);
    gain.connect(this.dry);
    gain.connect(this.verbSend);
  }

  pluck(time, note, params) {
    const osc = this.ctx.createOscillator();
    const filter = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();
    osc.type = params.type;
    osc.frequency.value = midi(note);
    filter.type = "lowpass";
    filter.frequency.setValueAtTime(params.cutoff * 2.5, time);
    filter.frequency.exponentialRampToValueAtTime(params.cutoff, time + 0.15);
    this.env(gain.gain, time, params.vol, 0.003, params.decay);
    osc.connect(filter).connect(gain);
    gain.connect(this.dry);
    gain.connect(this.delaySend);
    gain.connect(this.verbSend);
    osc.start(time);
    osc.stop(time + params.decay + 0.1);
  }

  stab(time, notes, params) {
    const filter = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();
    filter.type = "lowpass";
    filter.frequency.setValueAtTime(params.cutoff * 2, time);
    filter.frequency.exponentialRampToValueAtTime(params.cutoff * 0.6, time + params.decay);
    this.env(gain.gain, time, params.vol, 0.004, params.decay);
    for (const note of notes) {
      const osc = this.ctx.createOscillator();
      osc.type = params.type;
      osc.frequency.value = midi(note);
      osc.connect(filter);
      osc.start(time);
      osc.stop(time + params.decay + 0.1);
    }
    filter.connect(gain);
    gain.connect(this.dry);
    gain.connect(this.delaySend);
    gain.connect(this.verbSend);
  }

  riser(time, duration) {
    const source = this.ctx.createBufferSource();
    const bandpass = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();
    source.buffer = this.noise;
    source.loop = true;
    bandpass.type = "bandpass";
    bandpass.Q.value = 2;
    bandpass.frequency.setValueAtTime(300, time);
    bandpass.frequency.exponentialRampToValueAtTime(8000, time + duration);
    gain.gain.setValueAtTime(0.0001, time);
    gain.gain.linearRampToValueAtTime(0.3, time + duration);
    gain.gain.linearRampToValueAtTime(0.0001, time + duration + 0.05);
    source.connect(bandpass).connect(gain);
    gain.connect(this.out);
    gain.connect(this.verbSend);
    source.start(time);
    source.stop(time + duration + 0.1);
  }
}

const lv = (step) => (step === "X" ? 1 : step === "x" ? 0.55 : 0);

class Ticker {
  constructor(callback) {
    this.callback = callback;
  }

  start() {
    const fallback = () => {
      this.interval ??= setInterval(this.callback, 25);
    };
    try {
      const source = ["setInterval(() => postMessage(0), 25)"];
      this.url = URL.createObjectURL(new Blob(source, { type: "text/javascript" }));
      this.worker = new Worker(this.url);
      this.worker.onmessage = this.callback;
      this.worker.onerror = () => {
        this.worker.terminate();
        fallback();
      };
    } catch {
      fallback();
    }
  }

  stop() {
    this.worker?.terminate();
    if (this.url) URL.revokeObjectURL(this.url);
    clearInterval(this.interval);
  }
}

export class Player {
  constructor(song, synth, onBar) {
    this.song = song;
    this.synth = synth;
    this.onBar = onBar;
    this.step = 0;
    this.t0 = synth.ctx.currentTime + 0.1;
    this.next = this.t0;
    synth.setSong(song);
    this.ticker = new Ticker(() => this.tick());
    this.ticker.start();
  }

  stop() {
    this.ticker.stop();
  }

  tick() {
    const stepDuration = 60 / this.song.bpm / 4;
    while (this.next < this.synth.ctx.currentTime + 0.3) {
      this.schedule(this.step, this.next);
      this.next += stepDuration;
      this.step += 1;
    }
  }

  schedule(step, time) {
    const { song, synth } = this;
    const bar = Math.floor(step / 16) % song.totalBars;
    const i = step % 16;
    const { section, index, barIn } = song.barMap[bar];
    const has = (layer) => section.layers.includes(layer);
    const chord = song.chords[Math.floor(bar / song.barsPerChord) % song.chords.length];
    const stepDuration = 60 / song.bpm / 4;
    const barDuration = stepDuration * 16;

    if (i === 0) {
      const delay = Math.max(0, (time - synth.ctx.currentTime) * 1000);
      setTimeout(
        () => this.onBar?.({ bar, index, total: song.totalBars, name: section.name }),
        delay,
      );
      if (section.riser && barIn === section.bars - 1) synth.riser(time, barDuration);
      if (has("pad") && bar % song.barsPerChord === 0) {
        const progress = barIn / section.bars;
        const notes = chord.t.map((offset) => song.root + 12 + chord.r + offset);
        synth.pad(time, notes, barDuration * song.barsPerChord, {
          ...song.sound.pad,
          cutoff: song.sound.pad.cutoff * (0.7 + 0.6 * progress),
        });
      }
    }

    const kick = has("kick") ? lv(song.kick[i]) : 0;
    if (kick) {
      synth.kick(time, song.sound.kick.vol * kick, song.sound.kick.decay);
      synth.pump(time, song.sound.duck);
    }

    const hat = has("hat") ? lv(song.hat[i]) : 0;
    if (hat) synth.hat(time, song.sound.hat * hat, false);

    const openHat = has("ohat") ? lv(song.ohat[i]) : 0;
    if (openHat) synth.hat(time, song.sound.ohat * openHat, true);

    const bassOffset = song.bass[i];
    if (has("bass") && bassOffset != null) {
      synth.bass(time, song.root + chord.r + bassOffset, stepDuration * 0.9, song.sound.bass);
    }

    const arpIndex = song.arp[i];
    if (has("arp") && arpIndex != null) {
      const notes = chord.t.length;
      const note =
        song.root + 24 + chord.r + chord.t[arpIndex % notes] + 12 * Math.floor(arpIndex / notes);
      synth.pluck(time, note, song.sound.arp);
    }

    if (has("stab") && lv(song.stab[i])) {
      synth.stab(
        time,
        chord.t.map((offset) => song.root + 12 + chord.r + offset),
        song.sound.stab,
      );
    }
  }
}

export class Scene {
  constructor(canvas, song) {
    this.canvas = canvas;
    this.setSong(song);
    this.g = canvas.getContext("2d");
    this.bins = new Uint8Array(512);
    this.level = { bass: 0, mid: 0, high: 0 };
    this.stars = Array.from({ length: 320 }, () => ({
      x: Math.random() * 2 - 1,
      y: Math.random() * 2 - 1,
      z: Math.random(),
    }));
    this.width = 0;
    this.height = 0;
    this.last = performance.now();
    this.source = null;
    this.motion = matchMedia("(prefers-reduced-motion: reduce)").matches ? 0.3 : 1;

    this.resize = this.resize.bind(this);
    new ResizeObserver(this.resize).observe(canvas);
    this.resize();
  }

  setSong(song) {
    this.colorA = song.rgb.join(",");
    this.colorB = song.rgb2.join(",");
  }

  setSource(source) {
    this.source = source;
  }

  start() {
    requestAnimationFrame((now) => this.frame(now));
  }

  resize() {
    const dpr = Math.min(devicePixelRatio || 1, 2);
    this.width = this.canvas.clientWidth;
    this.height = this.canvas.clientHeight;
    this.canvas.width = Math.round(this.width * dpr);
    this.canvas.height = Math.round(this.height * dpr);
    this.g.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  average(from, to) {
    let total = 0;
    for (let i = from; i < to; i++) total += this.bins[i];
    return total / (to - from) / 255;
  }

  readAudio() {
    let bass = 0;
    let mid = 0;
    let high = 0;
    if (this.source) {
      this.source.synth.analyser.getByteFrequencyData(this.bins);
      bass = this.average(1, 5);
      mid = this.average(5, 30);
      high = this.average(30, 150);
    }
    for (const [key, value] of [
      ["bass", bass],
      ["mid", mid],
      ["high", high],
    ]) {
      this.level[key] += (value - this.level[key]) * (value > this.level[key] ? 0.5 : 0.1);
    }
  }

  frame(now) {
    const delta = Math.min((now - this.last) / 1000, 0.05);
    this.last = now;
    this.readAudio();

    const { g, width: W, height: H, level, motion, source, colorA, colorB } = this;

    g.fillStyle = "#05060d";
    g.fillRect(0, 0, W, H);

    g.globalCompositeOperation = "lighter";
    for (let k = 0; k < 3; k++) {
      const x = W * (0.5 + 0.28 * Math.sin(now * 0.00021 * (k + 1) + k * 2));
      const y = H * (0.5 + 0.22 * Math.cos(now * 0.00017 * (k + 2) + k));
      const radius = Math.max(W, H) * (0.28 + k * 0.05 + level.bass * 0.25 * motion);
      const gradient = g.createRadialGradient(x, y, 0, x, y, radius);
      const color = k === 1 ? colorB : colorA;
      const alpha = 0.28 + level.mid * 0.35 * motion;
      gradient.addColorStop(0, `rgba(${color},${alpha})`);
      gradient.addColorStop(0.4, `rgba(${color},${alpha * 0.42})`);
      gradient.addColorStop(1, `rgba(${color},0)`);
      g.fillStyle = gradient;
      g.fillRect(0, 0, W, H);
    }
    g.globalCompositeOperation = "source-over";

    const speed = (0.05 + level.bass * 0.4) * motion;
    const cx = W / 2;
    const cy = H / 2;
    const scale = Math.max(W, H) * 0.6;
    g.lineCap = "round";
    for (const star of this.stars) {
      const previous = star.z + speed * delta * 1.5;
      star.z -= speed * delta;
      if (star.z < 0.02) {
        star.x = Math.random() * 2 - 1;
        star.y = Math.random() * 2 - 1;
        star.z = 1;
        continue;
      }
      g.strokeStyle = `rgba(230,235,255,${(1 - star.z) * (0.5 + level.high * 0.5)})`;
      g.lineWidth = 0.5 + (1 - star.z) * 1.8;
      g.beginPath();
      g.moveTo(cx + (star.x / previous) * scale * 0.2, cy + (star.y / previous) * scale * 0.2);
      g.lineTo(cx + (star.x / star.z) * scale * 0.2, cy + (star.y / star.z) * scale * 0.2);
      g.stroke();
    }

    if (source) {
      const bars = 40;
      const barWidth = W / bars;
      g.fillStyle = `rgba(${colorA},0.65)`;
      for (let bar = 0; bar < bars; bar++) {
        const value = this.bins[Math.floor(1 + (bar / bars) ** 2 * 180)] / 255;
        const height = 3 + value * 30;
        g.fillRect(bar * barWidth + 1, H - height, barWidth - 2, height);
      }
    }

    requestAnimationFrame((next) => this.frame(next));
  }
}

export function createUI({ songs, selected, onToggle, onSelect, onNext, onVolume }) {
  const title = document.querySelector("#nowTitle");
  const section = document.querySelector("#nowSection");
  const volume = document.querySelector("#vol");
  const floatingButton = document.querySelector(".play-floating");
  const nextButton = document.querySelector(".next-floating");
  const pendingText = "Pulsa para activar el audio";
  let currentSong = selected;
  let lastInfo = null;
  let audioPending = false;

  const cards = songs.map((song) => {
    const card = document.createElement("article");
    card.className = "card";
    card.style.setProperty("--c", song.color);
    card.innerHTML = `
      <h2>${song.name}</h2>
      <p class="mood">${song.mood}</p>
      <div class="chips"><span>${song.bpm} BPM</span><span>${song.key}</span><span>${song.totalBars} compases</span></div>
      <div class="map" aria-hidden="true">${song.sections
        .map(
          ({ name, bars }) =>
            `<span class="seg" style="flex:${bars}" title="${name}, ${bars} compases"></span>`,
        )
        .join("")}</div>
      <div class="where" aria-live="off"></div>
      <button class="play" type="button" aria-pressed="false">Reproducir</button>`;
    document.querySelector("#tracks").append(card);
    return {
      song,
      card,
      button: card.querySelector(".play"),
      where: card.querySelector(".where"),
      segments: [...card.querySelectorAll(".seg")],
    };
  });

  for (const entry of cards) {
    entry.button.addEventListener("click", () => onSelect(entry.song));
  }
  floatingButton.addEventListener("click", onToggle);
  nextButton.addEventListener("click", onNext);
  volume.addEventListener("input", (event) => onVolume(Number(event.target.value)));

  function writeSection(text) {
    section.textContent = audioPending ? pendingText : text;
  }

  function paint(state) {
    for (const entry of cards) {
      const playing = entry.song === currentSong && Boolean(state);
      entry.card.classList.toggle("on", playing);
      entry.card.classList.toggle("selected", entry.song === currentSong);
      entry.button.setAttribute("aria-pressed", String(playing));
      entry.button.textContent = playing ? "Detener" : "Reproducir";
      entry.where.textContent = playing
        ? `${state.name} · compás ${state.bar + 1}/${state.total}`
        : "";
      entry.segments.forEach((segment, index) => {
        segment.classList.toggle("now", playing && index === state.index);
        segment.classList.toggle("done", playing && index < state.index);
      });
    }
    floatingButton.setAttribute("aria-pressed", String(Boolean(state)));
    floatingButton.textContent = audioPending ? "Activar audio" : state ? "Detener" : "Reproducir";
    const next = songs[(songs.indexOf(currentSong) + 1) % songs.length];
    nextButton.title = `Siguiente: ${next.name}`;
    nextButton.setAttribute("aria-label", `Siguiente tema: ${next.name}`);
  }

  return {
    showSelected(song) {
      currentSong = song;
      lastInfo = null;
      paint(null);
      title.textContent = song.name;
      writeSection("Pulsa reproducir para despegar");
    },
    showPlaying(info) {
      lastInfo = info;
      paint(info);
      title.textContent = currentSong.name;
      writeSection(info.name);
    },
    showStopped() {
      lastInfo = null;
      paint(null);
      title.textContent = "En reposo";
      writeSection("Pulsa reproducir para despegar");
    },
    showError(message) {
      section.textContent = message;
    },
    setAudioPending(value) {
      audioPending = value;
      paint(lastInfo);
      writeSection(lastInfo ? lastInfo.name : "Pulsa reproducir para despegar");
    },
  };
}
